<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { orderApi } from '../../services/customerApi';
import { demoOrder } from '../../mock/customerDemo';
const props = defineProps({ stage: { type: String, default: 'tracking' } }); const route = useRoute(); const router = useRouter(); const order = ref(null); const error = ref('');
const metadata = { pending: ['Chờ shop xác nhận', 'Yêu cầu thuê đã được gửi sau khi thanh toán.'], receive: ['Nhận đồ', 'Kiểm tra trang phục cùng người giao hàng trước khi nhận.'], return: ['Trả đồ', 'Đặt lịch trả đồ đúng thời hạn đã thỏa thuận.'], tracking: ['Theo dõi đơn thuê', 'Theo dõi tiến trình thuê đồ của bạn.'], refund: ['Hoàn cọc', 'Tiền cọc sẽ được xử lý sau khi chủ shop xác nhận trả đồ.'], cancel: ['Hủy đơn', 'Bạn có thể gửi yêu cầu hủy theo chính sách của shop.'], review: ['Đánh giá đơn thuê', 'Chia sẻ trải nghiệm thuê đồ của bạn.'], complaint: ['Khiếu nại', 'Gửi thông tin và bằng chứng để được hỗ trợ.'] };
const info = computed(() => metadata[props.stage] || metadata.tracking); const steps = [{ key: 'PENDING', label: 'Chờ xác nhận', icon: 'bi-hourglass-split' }, { key: 'CONFIRMED', label: 'Shop xác nhận', icon: 'bi-patch-check' }, { key: 'READY', label: 'Chuẩn bị đồ', icon: 'bi-box-seam' }, { key: 'SHIPPING', label: 'Đang giao', icon: 'bi-truck' }, { key: 'RENTING', label: 'Đang thuê', icon: 'bi-stars' }, { key: 'RETURNED', label: 'Đã trả đồ', icon: 'bi-arrow-return-left' }, { key: 'COMPLETED', label: 'Hoàn tất', icon: 'bi-check2-circle' }];
const progress = computed(() => Math.max(0, steps.findIndex((step) => step.key === order.value?.status)));
const action = computed(() => ({ receive: ['Xác nhận đã nhận đồ', 'bi-box2-heart'], return: ['Tạo lịch trả đồ', 'bi-calendar-check'], refund: ['Xem chi tiết hoàn cọc', 'bi-wallet2'], cancel: ['Gửi yêu cầu hủy', 'bi-x-circle'], tracking: ['Liên hệ chủ đồ', 'bi-chat-dots'] }[props.stage]));
async function load() { if (route.query.demo === '1') { order.value = demoOrder; return; } if (!route.params.id) return; try { order.value = (await orderApi.detail(route.params.id)).data; } catch (e) { error.value = e.response?.data?.error?.message || 'Không thể tải đơn thuê.'; } }
onMounted(load);
</script>
<template><div class="stage-page py-4"><div class="container"><button class="btn btn-link p-0 mb-4 text-decoration-none" @click="router.push('/customer/orders')"><i class="bi bi-arrow-left"></i> Đơn thuê của tôi</button><header class="stage-hero"><div><span class="eyebrow">ĐƠN THUÊ #{{ order?.id?.slice(-6)?.toUpperCase() || 'DEMO' }}</span><h1 class="display-6 fw-bold mb-2">{{ info[0] }}</h1><p class="mb-0 text-muted">{{ info[1] }}</p></div><span class="status-pill"><i class="bi bi-truck"></i> {{ order?.status || 'ĐANG XỬ LÝ' }}</span></header><div v-if="error" class="alert alert-warning mt-3">{{ error }}</div><section class="timeline-card mt-4"><h2 class="h5 mb-4">Hành trình đơn thuê</h2><div class="timeline"><div v-for="(step, index) in steps" :key="step.key" class="timeline-step" :class="{ done: index <= progress }"><div class="step-icon"><i :class="`bi ${step.icon}`"></i></div><div><strong>{{ step.label }}</strong><small v-if="index === progress" class="d-block">Đang cập nhật từ chủ đồ</small></div></div></div></section><div class="row g-4 mt-1"><section class="col-lg-7"><div class="detail-card"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Sản phẩm thuê</h2><span class="text-muted small">{{ order?.shop?.name }}</span></div><div v-for="item in order?.orderItems || []" :key="item.id" class="product-line"><div class="product-thumb"><i class="bi bi-person-bounding-box"></i></div><div class="flex-grow-1"><strong>{{ item.productName }}</strong><span class="d-block small text-muted">{{ new Date(item.startDate).toLocaleDateString('vi-VN') }} — {{ new Date(item.endDate).toLocaleDateString('vi-VN') }} · {{ item.quantity }} bộ</span></div></div><div v-if="!order" class="text-muted">Thông tin đơn sẽ hiện khi API khả dụng.</div></div></section><aside class="col-lg-5"><div class="detail-card"><h2 class="h5">Giao nhận & hỗ trợ</h2><div class="info-row"><i class="bi bi-geo-alt"></i><span>Địa chỉ giao nhận đã xác nhận trong đơn thuê</span></div><div class="info-row"><i class="bi bi-shield-check"></i><span>Tiền cọc được Clarity giữ đến khi hoàn trả đồ.</span></div><button v-if="action" class="btn btn-primary w-100 mt-3"><i :class="`bi ${action[1]} me-2`"></i>{{ action[0] }}</button></div></aside></div><section v-if="stage === 'review'" class="detail-card mt-4"><h2 class="h5">Bạn hài lòng với đơn thuê này chứ?</h2><div class="stars my-3"><button v-for="n in 5" :key="n" class="btn p-0"><i class="bi bi-star-fill"></i></button></div><textarea class="form-control" rows="3" placeholder="Chia sẻ trải nghiệm của bạn"></textarea><button class="btn btn-primary mt-3" @click="router.push('/customer/orders')">Gửi đánh giá</button></section><section v-if="stage === 'complaint' || stage === 'cancel'" class="detail-card mt-4"><h2 class="h5">{{ stage === 'cancel' ? 'Lý do hủy đơn' : 'Nội dung khiếu nại' }}</h2><select class="form-select mb-2"><option>Chọn lý do</option><option>Thay đổi lịch cá nhân</option><option>Sản phẩm không đúng mô tả</option></select><textarea class="form-control" rows="3" placeholder="Mô tả chi tiết để Clarity hỗ trợ"></textarea><button class="btn btn-danger mt-3">Gửi yêu cầu</button></section></div></div></template>
<style scoped>.stage-page{background:#faf8f5;min-height:72vh}.stage-hero,.timeline-card,.detail-card{background:#fff;border:1px solid #e9e1d9;border-radius:16px;padding:1.5rem}.stage-hero{display:flex;justify-content:space-between;gap:1rem;align-items:center;background:linear-gradient(115deg,#fff 10%,#f2ebe4)}.eyebrow{color:var(--bs-accent);font-size:.75rem;font-weight:800;letter-spacing:.12em}.status-pill{background:#4a3b32;color:#fff;border-radius:999px;padding:.55rem .8rem;font-size:.8rem;font-weight:700}.timeline{display:grid;grid-template-columns:repeat(7,1fr);gap:.4rem}.timeline-step{color:#a39b94;font-size:.75rem;text-align:center;position:relative}.timeline-step:not(:last-child)::after{content:'';height:2px;background:#ddd5ce;position:absolute;width:calc(100% - 28px);left:calc(50% + 14px);top:14px}.step-icon{position:relative;z-index:1;width:30px;height:30px;margin:0 auto .45rem;border-radius:50%;display:grid;place-items:center;background:#ece7e2}.done{color:var(--bs-primary);font-weight:700}.done .step-icon{background:var(--bs-primary);color:#fff}.done:not(:last-child)::after{background:var(--bs-primary)}.product-line{display:flex;gap:1rem;border-top:1px solid #eee7e0;margin-top:1rem;padding-top:1rem}.product-thumb{width:52px;height:64px;border-radius:8px;background:#eee5dc;display:grid;place-items:center;font-size:1.5rem}.info-row{display:flex;gap:.75rem;margin:1rem 0;color:#655d57;font-size:.9rem}.stars button{color:#d69d31;font-size:1.5rem}@media(max-width:767px){.stage-hero{align-items:flex-start;flex-direction:column}.timeline{grid-template-columns:1fr}.timeline-step{display:flex;text-align:left;gap:.75rem;align-items:center}.timeline-step:not(:last-child)::after{width:2px;height:22px;left:14px;top:30px}}</style>
